var n=`0607-mechoui`;var i=`world-0607`;var r=`MA`;var s=`northern-africa`;var a=4;var o=298;var l={en:`Mechoui`,ua:`Мешуї`};var g={en:`Mechoui is a Morocco classic prepared with lamb shoulder, garlic, parsley, lemon. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мешуї, страва кухні країни Марокко зі складниками: лопатка ягняти, часник, петрушка, лимон. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 120 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 120 хвилин.`,t:[`marinating`],m:120,i:[[`lamb-shoulder`,1250,`g`],[`garlic`,5,`clove`],[`ground-cumin`,7,`g`],[`ground-coriander`,4,`g`],[`extra-virgin-olive-oil`,50,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Roast the seasoned lamb covered until tender, then uncover to brown its surface. Check doneness with a thermometer and rest before cutting.`,ua:`Запікайте приправлену баранину під накриттям до м’якості, потім відкрийте для рум’яної скоринки. Перевірте готовність термометром і дайте відпочити.`,t:[`roasting`],m:175,i:[[`water`,200,`ml`],[`unsalted-butter`,45,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`],[`lemon`,1,`pcs`]]}];var c={slug:n,id:i,country:`MA`,region:s,servings:4,minutes:298,title:l,text:g,steps:u};export{r as country,c as default,i as id,o as minutes,s as region,a as servings,n as slug,u as steps,g as text,l as title};